import React from 'react';
import './Home.css';

function Home() {
  const bikes = [
    {
      name: 'Yamaha R15',
      img: 'https://imgd.aeplcdn.com/664x374/n/cw/ec/140199/r15-v4-right-front-three-quarter.jpeg',
      link: '/product/yamaha-r15', // Example link, change as needed
    },
    {
      name: 'Royal Enfield Classic 350',
      img: '',
      link: '/product/royal-enfield-classic-350', // Example link
    },
    {
      name: 'Honda Shine',
      img: 'https://imgd.aeplcdn.com/664x374/n/cw/ec/141335/shine-right-front-three-quarter.jpeg',
      link: '/product/honda-shine', // Example link
    },
  ];

  return (
    <div className="home">
      <h1>Welcome to TwoWheeler</h1>
      <p>Buy or rent your favorite bikes at the best prices!</p>

      <div className="product-grid">
        {bikes.map((bike, index) => (
          <div className="product-card" key={index}>
            <img src={bike.img} alt={bike.name} />
            <h3>{bike.name}</h3>
            <a href={bike.link} className="btn-view-details">View Details</a>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Home;
